function describe(node, depth) {
  if (!node) return null;
  const o = { id: node.id, name: node.name, type: node.type, width: node.width, height: node.height };
  if ('fills' in node && node.fills !== figma.mixed) o.fills = node.fills;
  if ('strokes' in node) o.strokes = node.strokes;
  if (depth > 0 && 'children' in node) {
    o.children = node.children.map(c => describe(c, depth - 1));
  }
  return o;
}
