function autoFrame(name, dir, opts){
  const f = figma.createFrame();
  f.name = name;
  f.layoutMode = dir;
  f.primaryAxisSizingMode = (opts && opts.primaryHug===false)?'FIXED':'AUTO';
  f.counterAxisSizingMode = (opts && opts.counterHug===false)?'FIXED':'AUTO';
  f.itemSpacing = (opts && opts.spacing!==undefined)?opts.spacing:8;
  f.paddingLeft = f.paddingRight = (opts && opts.padX!==undefined)?opts.padX:0;
  f.paddingTop = f.paddingBottom = (opts && opts.padY!==undefined)?opts.padY:0;
  if(opts && opts.fill) f.fills=[solid(opts.fill)]; else f.fills=[];
  if(opts && opts.radius!==undefined) f.cornerRadius = opts.radius;
  if(opts && opts.primaryAlign) f.primaryAxisAlignItems = opts.primaryAlign;
  if(opts && opts.counterAlign) f.counterAxisAlignItems = opts.counterAlign;
  if(opts && opts.clip!==undefined) f.clipsContent = opts.clip;
  return f;
}
