async function buildBottomNav(activeKey){
  const items = [
    {key:'home', id:'1:190'},
    {key:'challenges', id:'1:189'},
    {key:'store', id:'1:192'},
    {key:'profile', id:'1:191'}
  ];
  const nav = figma.createComponent();
  nav.name = 'BottomNav/'+activeKey;
  nav.layoutMode='HORIZONTAL';
  nav.primaryAxisAlignItems='SPACE_BETWEEN';
  nav.counterAxisAlignItems='CENTER';
  nav.primaryAxisSizingMode='FIXED';
  nav.counterAxisSizingMode='FIXED';
  nav.resize(375,84);
  nav.paddingLeft=nav.paddingRight=40;
  nav.paddingTop=14; nav.paddingBottom=30;
  nav.fills=[solid(C.surface)];
  nav.strokes=[solid(C.stroke)];
  nav.strokeWeight=1;
  nav.strokeAlign='INSIDE';
  for(const it of items){
    const active = it.key===activeKey;
    const wrap = hFrame('NavItem', {primaryFixed:true, counterFixed:true, w:40,h:40, radius:14, fill: active?C.brandSoft:undefined, align:'CENTER', primaryAlign:'CENTER'});
    const ic = await getIcon(it.id, 22, active?C.brand:C.textTer);
    wrap.appendChild(ic);
    nav.appendChild(wrap);
  }
  nav.x=-3000; nav.y = activeKey==='home'? -850 : -750;
  return nav;
}
