function txt(content, size, weight, color, opts){
  const t = figma.createText();
  t.fontName = {family:'Poppins', style:weight};
  t.characters = content;
  t.fontSize = size;
  t.fills = [solid(color)];
  if(opts && opts.align) t.textAlignHorizontal = opts.align;
  if(opts && opts.grow) t.layoutGrow = 1;
  return t;
}
function recolorIconTree(node, hexColor){
  if('fills' in node && Array.isArray(node.fills) && node.fills.length>0){
    const newFills = node.fills.map(f=> f.type==='SOLID' ? Object.assign({}, f, {color:hx(hexColor), opacity:1}) : f);
    try{ node.fills = newFills; }catch(e){}
  }
  if('strokes' in node && Array.isArray(node.strokes) && node.strokes.length>0){
    const newStrokes = node.strokes.map(s=> s.type==='SOLID' ? Object.assign({}, s, {color:hx(hexColor), opacity:1}) : s);
    try{ node.strokes = newStrokes; }catch(e){}
  }
  if('children' in node){ for(const c of node.children) recolorIconTree(c, hexColor); }
}
async function getIcon(id, size, hexColor){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  inst.resize(size, size);
  if(hexColor) recolorIconTree(inst, hexColor);
  return inst;
}
async function getIconAspect(id, h, hexColor){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  const ratio = comp.width/comp.height;
  inst.resize(h*ratio, h);
  if(hexColor) recolorIconTree(inst, hexColor);
  return inst;
}
async function getAsset(id, w, h){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  if(w && h) inst.resize(w,h);
  return inst;
}
function vFrame(name, opts){
  const f=figma.createFrame(); f.name=name;
  f.layoutMode='VERTICAL';
  f.itemSpacing=opts.spacing||0;
  f.primaryAxisSizingMode=opts.primaryFixed?'FIXED':'AUTO';
  f.counterAxisSizingMode=opts.counterFixed?'FIXED':'AUTO';
  if(opts.w||opts.h) f.resize(opts.w||f.width, opts.h||f.height);
  f.paddingLeft=f.paddingRight=opts.padX||0;
  f.paddingTop=f.paddingBottom=opts.padY||0;
  f.fills = opts.fill?[solid(opts.fill)]:[];
  if(opts.radius!==undefined) f.cornerRadius=opts.radius;
  if(opts.align) f.counterAxisAlignItems=opts.align;
  if(opts.primaryAlign) f.primaryAxisAlignItems=opts.primaryAlign;
  return f;
}
function hFrame(name, opts){
  const f=figma.createFrame(); f.name=name;
  f.layoutMode='HORIZONTAL';
  f.itemSpacing=opts.spacing||0;
  f.primaryAxisSizingMode=opts.primaryFixed?'FIXED':'AUTO';
  f.counterAxisSizingMode=opts.counterFixed?'FIXED':'AUTO';
  if(opts.w||opts.h) f.resize(opts.w||f.width, opts.h||f.height);
  f.paddingLeft=f.paddingRight=opts.padX||0;
  f.paddingTop=f.paddingBottom=opts.padY||0;
  f.fills = opts.fill?[solid(opts.fill)]:[];
  if(opts.radius!==undefined) f.cornerRadius=opts.radius;
  if(opts.align) f.counterAxisAlignItems=opts.align;
  if(opts.primaryAlign) f.primaryAxisAlignItems=opts.primaryAlign;
  return f;
}
function ringNode(size, fraction, trackColor, fillColor, trackOpacity){
  const f = figma.createFrame();
  f.name='Ring';
  f.resize(size,size);
  f.fills=[];
  const track = figma.createEllipse();
  track.resize(size,size);
  track.fills=[solid(trackColor, trackOpacity===undefined?1:trackOpacity)];
  track.arcData = {startingAngle:0, endingAngle: Math.PI*2, innerRadius:0.82};
  f.appendChild(track);
  const prog = figma.createEllipse();
  prog.resize(size,size);
  prog.fills=[solid(fillColor)];
  prog.arcData = {startingAngle:-Math.PI/2, endingAngle: -Math.PI/2 + fraction*Math.PI*2, innerRadius:0.82};
  f.appendChild(prog);
  return f;
}

