function recolorIconTree(node, hexColor){
  if('fills' in node && Array.isArray(node.fills) && node.fills.length>0){
    const newFills = node.fills.map(f=> f.type==='SOLID' ? Object.assign({}, f, {color:hx(hexColor), opacity:1}) : f);
    try{ node.fills = newFills; }catch(e){}
  }
  if('strokes' in node && Array.isArray(node.strokes) && node.strokes.length>0){
    const newStrokes = node.strokes.map(s=> s.type==='SOLID' ? Object.assign({}, s, {color:hx(hexColor), opacity:1}) : s);
    try{ node.strokes = newStrokes; }catch(e){}
  }
  if('children' in node){ for(const c of node.children) recolorIconTree(c, hexColor); }
}
async function getIcon(id, size, hexColor){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  inst.resize(size, size);
  if(hexColor) recolorIconTree(inst, hexColor);
  return inst;
}
