function hx(h){h=h.replace('#','');return {r:parseInt(h.substring(0,2),16)/255,g:parseInt(h.substring(2,4),16)/255,b:parseInt(h.substring(4,6),16)/255};}
function solid(h,o){return {type:'SOLID',color:hx(h),opacity:(o===undefined?1:o)};}
