function txt(content, size, weight, color, opts){
  const t = figma.createText();
  t.fontName = {family:'Poppins', style:weight};
  t.characters = content;
  t.fontSize = size;
  t.fills = [solid(color)];
  if(opts && opts.align) t.textAlignHorizontal = opts.align;
  return t;
}
async function getAsset(id, w, h){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  if(w && h) inst.resize(w,h);
  return inst;
}
function vFrame(name, opts){
  const f=figma.createFrame(); f.name=name;
  f.layoutMode='VERTICAL';
  f.itemSpacing=opts.spacing||0;
  f.primaryAxisSizingMode=opts.primaryFixed?'FIXED':'AUTO';
  f.counterAxisSizingMode=opts.counterFixed?'FIXED':'AUTO';
  if(opts.w||opts.h) f.resize(opts.w||f.width, opts.h||f.height);
  f.paddingLeft=f.paddingRight=opts.padX||0;
  f.paddingTop=f.paddingBottom=opts.padY||0;
  f.fills = opts.fill?[solid(opts.fill)]:[];
  if(opts.radius!==undefined) f.cornerRadius=opts.radius;
  if(opts.align) f.counterAxisAlignItems=opts.align;
  if(opts.primaryAlign) f.primaryAxisAlignItems=opts.primaryAlign;
  return f;
}
async function addShellOverlay(frame){
  const sb = await getAsset('1:31', 375,44);
  sb.x=0; sb.y=0; sb.name='Status Bar';
  frame.appendChild(sb);
  const hi = await getAsset('1:41', 375,34);
  hi.x=0; hi.y=frame.height-34; hi.name='Home Indicator';
  frame.appendChild(hi);
}
function newScreen(name,w,h){
  const f = figma.createFrame();
  f.name=name; f.resize(w,h);
  f.fills=[solid(C.bg)];
  f.clipsContent=true;
  return f;
}

